import ExcelJS from 'exceljs';
import { saveAs } from 'file-saver';

/**
 * Generates a styled, human-readable multi-sheet Excel file of the show configuration
 */
export async function exportShowWorkbook(project) {
  const formatMsToTimeString = (ms) => {
    if (ms === undefined || ms === null || isNaN(ms)) return '00:00.000';
    const mins = Math.floor(ms / 60000);
    const secs = Math.floor((ms % 60000) / 1000);
    const msecs = Math.floor(ms % 1000);
    return `${mins.toString().padStart(2, '0')}:${secs.toString().padStart(2, '0')}.${msecs.toString().padStart(3, '0')}`;
  };

  const workbook = new ExcelJS.Workbook();
  workbook.creator = 'Magic Smoke - Great Balls of Fire';
  workbook.lastModifiedBy = 'Magic Smoke';
  workbook.created = new Date();
  workbook.modified = new Date();

  // ----------------------------------------------------
  // SHEET 1: Script
  // ----------------------------------------------------
  const scriptSheet = workbook.addWorksheet('Script');
  scriptSheet.views = [{ showGridLines: true }];

  const sortedEvents = [...(project.events || [])].sort((a, b) => {
    const aTime = a.desired_time_ms !== undefined ? a.desired_time_ms : (a.timestamp_offset_ms || 0);
    const bTime = b.desired_time_ms !== undefined ? b.desired_time_ms : (b.timestamp_offset_ms || 0);
    return aTime - bTime;
  });

  const columns = [
    { header: 'Event/Effect ID', key: 'event_id', width: 16 },
    { header: 'Time Offset (mm:ss.xxx)', key: 'time_formatted', width: 24 },
    { header: 'Event/Effect Title', key: 'title', width: 45 },
    { header: 'Machine Time (ms)', key: 'time_ms', width: 18 },
    { header: 'Machine Time (s)', key: 'time_s', width: 16 },
    { header: 'Song Start', key: 'song_start', width: 25 },
    
    // Group 1 (Left Field)
    { header: 'Board Hostname (Left)', key: 'board_left', width: 20 },
    { header: 'Location (Left)', key: 'loc_left', width: 16 },
    { header: 'Relay Port (Left)', key: 'relay_left', width: 14 },
    { header: 'Firework Name (Left)', key: 'fw_left', width: 32 },
    { header: 'Duration (Left) (s)', key: 'dur_left', width: 14 },
    { header: 'Wiring Type (Left)', key: 'wire_left', width: 16 },

    // Separator
    { header: '', key: 'sep_center', width: 4 },

    // Group 2 (Center Field)
    { header: 'Board Hostname (Center)', key: 'board_center', width: 20 },
    { header: 'Location (Center)', key: 'loc_center', width: 16 },
    { header: 'Relay Port (Center)', key: 'relay_center', width: 14 },
    { header: 'Firework Name (Center)', key: 'fw_center', width: 32 },
    { header: 'Duration (Center) (s)', key: 'dur_center', width: 14 },
    { header: 'Wiring Type (Center)', key: 'wire_center', width: 16 },

    // Separator
    { header: '', key: 'sep_right', width: 4 },

    // Group 3 (Right Field)
    { header: 'Board Hostname (Right)', key: 'board_right', width: 20 },
    { header: 'Location (Right)', key: 'loc_right', width: 16 },
    { header: 'Relay Port (Right)', key: 'relay_right', width: 14 },
    { header: 'Firework Name (Right)', key: 'fw_right', width: 32 },
    { header: 'Duration (Right) (s)', key: 'dur_right', width: 14 },
    { header: 'Wiring Type (Right)', key: 'wire_right', width: 16 }
  ];

  scriptSheet.columns = columns;

  // Style Header Row
  const headerRow = scriptSheet.getRow(1);
  headerRow.height = 28;
  headerRow.eachCell((cell, colNumber) => {
    const isSeparator = colNumber === 13 || colNumber === 20;

    if (isSeparator) {
      cell.fill = {
        type: 'pattern',
        pattern: 'solid',
        fgColor: { argb: 'FF7F8C8D' } // Medium gray header for separator
      };
    } else {
      cell.fill = {
        type: 'pattern',
        pattern: 'solid',
        fgColor: { argb: 'FF1F497D' } // Dark slate blue
      };
      cell.font = {
        name: 'Segoe UI',
        size: 11,
        bold: true,
        color: { argb: 'FFFFFFFF' }
      };
      cell.alignment = { vertical: 'middle', horizontal: 'center' };
    }
  });

  // Populate events
  sortedEvents.forEach((evt, evtIndex) => {
    const isSong = !!evt.song;
    const timeMs = evt.desired_time_ms !== undefined ? evt.desired_time_ms : (evt.timestamp_offset_ms || 0);

    const rowData = {
      event_id: evt.event_num,
      time_formatted: formatMsToTimeString(timeMs),
      title: isSong ? (evt.title || evt.song) : (evt.title || ''),
      time_ms: timeMs,
      time_s: parseFloat((timeMs / 1000).toFixed(3)),
      song_start: isSong ? evt.song : ''
    };

    if (!isSong && evt.relays && evt.relays.length > 0) {
      // Group by location_id and relay_idx for parallel wiring consolidation
      const relayGroups = {};
      evt.relays.forEach(r => {
        const key = `${r.location_id || ''}_${r.relay_idx}`;
        if (!relayGroups[key]) {
          relayGroups[key] = {
            location_id: r.location_id || '',
            relay_idx: r.relay_idx,
            fireworks: {},
            max_duration_ms: 0
          };
        }
        const g = relayGroups[key];
        g.fireworks[r.firework_name || 'Unknown'] = (g.fireworks[r.firework_name || 'Unknown'] || 0) + 1;
        if ((r.duration_ms || 2000) > g.max_duration_ms) {
          g.max_duration_ms = r.duration_ms || 2000;
        }
      });
      const consolidatedList = Object.values(relayGroups);

      const leftGroup = [];
      const centerGroup = [];
      const rightGroup = [];

      consolidatedList.forEach(g => {
        const loc = (g.location_id || '').toUpperCase();
        if (loc.startsWith('L') || loc.startsWith('LF') || loc.startsWith('LB')) {
          leftGroup.push(g);
        } else if (loc.startsWith('C') || loc === 'HP' || loc === 'CMD') {
          centerGroup.push(g);
        } else if (loc.startsWith('R') || loc.startsWith('RF') || loc.startsWith('RB')) {
          rightGroup.push(g);
        } else {
          centerGroup.push(g);
        }
      });

      const populateFieldGroup = (groupList, keySuffix) => {
        if (!groupList || groupList.length === 0) return;

        const hostnames = [];
        const locations = [];
        const relays = [];
        const fireworks = [];
        const durations = [];
        const wirings = [];

        groupList.forEach(g => {
          const locInfo = (project.locations || []).find(l => l.location_id === g.location_id);
          const hostname = locInfo ? (locInfo.node_hostname || '') : '';
          hostnames.push(hostname);
          locations.push(g.location_id);
          relays.push(g.relay_idx);

          // Formulate consolidated Firework Name
          let consolidatedName = '';
          const names = Object.keys(g.fireworks);
          if (names.length === 1) {
            const name = names[0];
            const cnt = g.fireworks[name];
            consolidatedName = cnt > 1 ? `${name} x${cnt}` : name;
          } else {
            const formattedList = names.map((name, idx) => {
              const letter = String.fromCharCode(97 + idx);
              const cnt = g.fireworks[name];
              const suffix = cnt > 1 ? ` x${cnt}` : '';
              return `(${letter}) ${name}${suffix}`;
            });
            consolidatedName = formattedList.join(' & ');
          }
          fireworks.push(consolidatedName);
          durations.push((g.max_duration_ms / 1000).toFixed(3));

          // Determine wiring
          let isFused = false;
          names.forEach(name => {
            const fw = (evt.fireworks || []).find(f => f.firework_name === name);
            if (fw && fw.is_fused) isFused = true;
          });
          wirings.push(isFused ? 'Fuse' : 'E-Match');
        });

        rowData[`board_${keySuffix}`] = hostnames.join(', ');
        rowData[`loc_${keySuffix}`] = locations.join(', ');
        rowData[`relay_${keySuffix}`] = relays.join(', ');
        rowData[`fw_${keySuffix}`] = fireworks.join(' & ');
        rowData[`dur_${keySuffix}`] = durations.length === 1 ? parseFloat(durations[0]) : durations.join(', ');
        rowData[`wire_${keySuffix}`] = wirings.join(', ');
      };

      populateFieldGroup(leftGroup, 'left');
      populateFieldGroup(centerGroup, 'center');
      populateFieldGroup(rightGroup, 'right');
    }

    const row = scriptSheet.addRow(rowData);
    row.height = 22;

    const isEven = evtIndex % 2 === 0;

    if (isSong) {
      for (let c = 1; c <= scriptSheet.columns.length; c++) {
        const cell = row.getCell(c);
        cell.font = { name: 'Segoe UI', size: 10, bold: true, color: { argb: 'FF4F2D7F' } };
        cell.alignment = { vertical: 'middle' };
        cell.border = {
          top: { style: 'thin', color: { argb: 'FFE0E0E0' } },
          bottom: { style: 'thin', color: { argb: 'FFE0E0E0' } },
          left: { style: 'thin', color: { argb: 'FFE0E0E0' } },
          right: { style: 'thin', color: { argb: 'FFE0E0E0' } }
        };
        cell.fill = {
          type: 'pattern',
          pattern: 'solid',
          fgColor: { argb: 'FFE8DFFF' } // Soft lavender/purple song marker
        };
      }
    } else {
      // Normal event row
      for (let c = 1; c <= scriptSheet.columns.length; c++) {
        const cell = row.getCell(c);
        cell.font = { name: 'Segoe UI', size: 10 };
        cell.alignment = { vertical: 'middle' };
        cell.border = {
          top: { style: 'thin', color: { argb: 'FFE0E0E0' } },
          bottom: { style: 'thin', color: { argb: 'FFE0E0E0' } },
          left: { style: 'thin', color: { argb: 'FFE0E0E0' } },
          right: { style: 'thin', color: { argb: 'FFE0E0E0' } }
        };

        // Align base columns (except title which is col 3)
        if (c <= 6) {
          if ([1, 2, 4, 5, 6].includes(c)) {
            cell.alignment = { vertical: 'middle', horizontal: 'center' };
          }
        }

        // Apply colors and separators
        const isSeparator = c === 13 || c === 20;
        if (isSeparator) {
          cell.fill = { type: 'pattern', pattern: 'solid', fgColor: { argb: 'FFD0D3D4' } };
          cell.border = {
            top: { style: 'thin', color: { argb: 'FFE0E0E0' } },
            bottom: { style: 'thin', color: { argb: 'FFE0E0E0' } }
          };
        } else if (c >= 7 && c <= 12) {
          // Left Field: Soft blue
          cell.fill = { type: 'pattern', pattern: 'solid', fgColor: { argb: 'FFD9E1F2' } };
          if (c !== 10) cell.alignment = { vertical: 'middle', horizontal: 'center' };
        } else if (c >= 14 && c <= 19) {
          // Center Field: Soft green
          cell.fill = { type: 'pattern', pattern: 'solid', fgColor: { argb: 'FFE2EFDA' } };
          if (c !== 17) cell.alignment = { vertical: 'middle', horizontal: 'center' };
        } else if (c >= 21 && c <= 26) {
          // Right Field: Soft orange-red
          cell.fill = { type: 'pattern', pattern: 'solid', fgColor: { argb: 'FFF5CBA7' } };
          if (c !== 24) cell.alignment = { vertical: 'middle', horizontal: 'center' };
        } else if (isEven) {
          // Alternating zebra fill for base columns
          cell.fill = { type: 'pattern', pattern: 'solid', fgColor: { argb: 'FFF2F2F2' } };
        }
      }
    }
  });

  // ----------------------------------------------------
  // SHEET 2: Song Tracks
  // ----------------------------------------------------
  const songSheet = workbook.addWorksheet('Song Tracks');
  songSheet.views = [{ showGridLines: true }];

  songSheet.columns = [
    { header: 'Song Number', key: 'song_num', width: 15 },
    { header: 'Start Time (mm:ss.xxx)', key: 'start_time_formatted', width: 24 },
    { header: 'Start Time (ms)', key: 'start_time_ms', width: 18 },
    { header: 'Start Time (s)', key: 'start_time_s', width: 15 },
    { header: 'Song Title', key: 'title', width: 35 },
    { header: 'Artist', key: 'artist', width: 30 }
  ];

  const songHeaderRow = songSheet.getRow(1);
  songHeaderRow.height = 28;
  songHeaderRow.eachCell((cell) => {
    cell.fill = {
      type: 'pattern',
      pattern: 'solid',
      fgColor: { argb: 'FF366092' } // Alternate Slate Blue
    };
    cell.font = { name: 'Segoe UI', size: 11, bold: true, color: { argb: 'FFFFFFFF' } };
    cell.alignment = { vertical: 'middle', horizontal: 'center' };
  });

  const songTracksList = [];
  (project.events || []).forEach(evt => {
    if (evt.song) {
      songTracksList.push({
        song_num: songTracksList.length + 1,
        start_time_ms: evt.timestamp_offset_ms || 0,
        title: evt.title || evt.song,
        artist: 'Magic Smoke'
      });
    }
  });

  songTracksList.forEach((song, idx) => {
    const row = songSheet.addRow({
      song_num: song.song_num,
      start_time_formatted: formatMsToTimeString(song.start_time_ms),
      start_time_ms: song.start_time_ms,
      start_time_s: parseFloat((song.start_time_ms / 1000).toFixed(2)),
      title: song.title || '',
      artist: song.artist || ''
    });
    row.height = 22;
    row.eachCell((cell) => {
      cell.font = { name: 'Segoe UI', size: 10 };
      cell.alignment = { vertical: 'middle', horizontal: 'center' };
      cell.border = {
        top: { style: 'thin', color: { argb: 'FFE0E0E0' } },
        bottom: { style: 'thin', color: { argb: 'FFE0E0E0' } },
        left: { style: 'thin', color: { argb: 'FFE0E0E0' } },
        right: { style: 'thin', color: { argb: 'FFE0E0E0' } }
      };
      if (idx % 2 === 0) {
        cell.fill = { type: 'pattern', pattern: 'solid', fgColor: { argb: 'FFF2F2F2' } };
      }
    });
    row.getCell('title').alignment = { vertical: 'middle', horizontal: 'left' };
    row.getCell('artist').alignment = { vertical: 'middle', horizontal: 'left' };
  });

  // ----------------------------------------------------
  // SHEET 3: Locations
  // ----------------------------------------------------
  const locSheet = workbook.addWorksheet('Locations');
  locSheet.views = [{ showGridLines: true }];

  locSheet.columns = [
    { header: 'Location ID', key: 'location_id', width: 16 },
    { header: 'ESP32 Node Hostname', key: 'node_hostname', width: 25 },
    { header: 'MAC Address', key: 'mac_addr', width: 22 }
  ];

  const locHeaderRow = locSheet.getRow(1);
  locHeaderRow.height = 28;
  locHeaderRow.eachCell((cell) => {
    cell.fill = {
      type: 'pattern',
      pattern: 'solid',
      fgColor: { argb: 'FF595959' } // Dark gray header
    };
    cell.font = { name: 'Segoe UI', size: 11, bold: true, color: { argb: 'FFFFFFFF' } };
    cell.alignment = { vertical: 'middle', horizontal: 'center' };
  });

  const { DEFAULT_SHOW_LOCATIONS } = require('./api');
  const finalLocations = DEFAULT_SHOW_LOCATIONS.map(defLoc => {
    const custom = (project.locations || []).find(l => l.location_id === defLoc.location_id);
    return custom ? custom : defLoc;
  });

  finalLocations.forEach((loc, idx) => {
    const row = locSheet.addRow({
      location_id: loc.location_id,
      node_hostname: loc.node_hostname || '',
      mac_addr: loc.mac_addr || ''
    });
    row.height = 22;
    row.eachCell((cell) => {
      cell.font = { name: 'Segoe UI', size: 10 };
      cell.alignment = { vertical: 'middle', horizontal: 'center' };
      cell.border = {
        top: { style: 'thin', color: { argb: 'FFE0E0E0' } },
        bottom: { style: 'thin', color: { argb: 'FFE0E0E0' } },
        left: { style: 'thin', color: { argb: 'FFE0E0E0' } },
        right: { style: 'thin', color: { argb: 'FFE0E0E0' } }
      };
      if (idx % 2 === 0) {
        cell.fill = { type: 'pattern', pattern: 'solid', fgColor: { argb: 'FFF2F2F2' } };
      }
    });
  });

  // Write and Save
  const buffer = await workbook.xlsx.writeBuffer();
  saveAs(new Blob([buffer]), `${project.name.replace(/\s+/g, '_')}_script.xlsx`);
}

/**
 * Exports a summarized wholesales order sheet with whole-integer ceiling rounded counts
 */
export async function exportInventoryOrderSheet(project) {
  const workbook = new ExcelJS.Workbook();
  const orderSheet = workbook.addWorksheet('Inventory Order Sheet');
  orderSheet.views = [{ showGridLines: true }];

  orderSheet.columns = [
    { header: 'Wholesale Firework Name', key: 'name', width: 35 },
    { header: 'Exact Plan Count (Fractional Sum)', key: 'fractional_count', width: 32 },
    { header: 'Required Order Quantity (Individual Fireworks)', key: 'rounded_count', width: 35 },
    { header: 'Box Packing Size (Units/Box)', key: 'packing_size', width: 28 },
    { header: 'Required Boxes to Order', key: 'boxes_count', width: 25 },
    { header: 'Extra Fireworks (Leftover Inventory)', key: 'extras_count', width: 32 }
  ];

  // Style Header Row
  const headerRow = orderSheet.getRow(1);
  headerRow.height = 28;
  headerRow.eachCell((cell) => {
    cell.fill = {
      type: 'pattern',
      pattern: 'solid',
      fgColor: { argb: 'FFC00000' } // Accent Red
    };
    cell.font = { name: 'Segoe UI', size: 11, bold: true, color: { argb: 'FFFFFFFF' } };
    cell.alignment = { vertical: 'middle', horizontal: 'center' };
  });

  // Collect distinct fireworks and count them including slice fractions
  const totals = {}; // { 'Firework Name': total_fractional_units }

  (project.events || []).forEach((evt) => {
    (evt.fireworks || []).forEach((fw) => {
      // Calculate multiplier from active fields
      let fieldCount = 0;
      if (fw.fields?.left) fieldCount++;
      if (fw.fields?.center) fieldCount++;
      if (fw.fields?.right) fieldCount++;

      // Slice fraction
      let sliceFraction = 1;
      if (fw.sliceSegment === '1/2') sliceFraction = 0.5;
      else if (fw.sliceSegment === '1/3') sliceFraction = 0.333333333;
      else if (fw.sliceSegment === '1/4') sliceFraction = 0.25;

      const delta = fw.quantity * fieldCount * sliceFraction;
      totals[fw.name] = (totals[fw.name] || 0) + delta;
    });
  });

  const { dbService } = require('./storage');
  const catalog = dbService.getCatalog() || [];

  const names = Object.keys(totals).sort();
  names.forEach((name, idx) => {
    const rawVal = totals[name];
    const roundedVal = Math.ceil(rawVal); // Whole integer ceiling function

    const catalogItem = catalog.find(item => item.name.toLowerCase() === name.toLowerCase());
    const boxQty = catalogItem && catalogItem.case_packing ? parseInt(catalogItem.case_packing) : 1;
    const requiredBoxes = Math.ceil(roundedVal / boxQty);
    const totalOrdered = requiredBoxes * boxQty;
    const extraLeftovers = totalOrdered - roundedVal;

    const row = orderSheet.addRow({
      name: name,
      fractional_count: parseFloat(rawVal.toFixed(3)),
      rounded_count: roundedVal,
      packing_size: `${boxQty}:1`,
      boxes_count: requiredBoxes,
      extras_count: extraLeftovers
    });
    row.height = 22;
    row.eachCell((cell) => {
      cell.font = { name: 'Segoe UI', size: 10 };
      cell.alignment = { vertical: 'middle' };
      cell.border = {
        top: { style: 'thin', color: { argb: 'FFE0E0E0' } },
        bottom: { style: 'thin', color: { argb: 'FFE0E0E0' } },
        left: { style: 'thin', color: { argb: 'FFE0E0E0' } },
        right: { style: 'thin', color: { argb: 'FFE0E0E0' } }
      };
      if (idx % 2 === 0) {
        cell.fill = { type: 'pattern', pattern: 'solid', fgColor: { argb: 'FFF2F2F2' } };
      }
    });

    row.getCell('fractional_count').alignment = { vertical: 'middle', horizontal: 'center' };
    row.getCell('rounded_count').alignment = { vertical: 'middle', horizontal: 'center' };
    row.getCell('packing_size').alignment = { vertical: 'middle', horizontal: 'center' };
    row.getCell('boxes_count').alignment = { vertical: 'middle', horizontal: 'center' };
    row.getCell('extras_count').alignment = { vertical: 'middle', horizontal: 'center' };
  });

  const buffer = await workbook.xlsx.writeBuffer();
  saveAs(new Blob([buffer]), `${project.name.replace(/\s+/g, '_')}_wholesaler_order.xlsx`);
}

/**
 * Imports a show workbook containing Script, Song Tracks, and Locations sheets
 * @param {File} file The uploaded Excel file object
 * @returns {Promise<Object>} Object containing parsed events, songTracks, and locations lists
 */
export async function importShowWorkbook(file) {
  const workbook = new ExcelJS.Workbook();
  const arrayBuffer = await file.arrayBuffer();
  await workbook.xlsx.load(arrayBuffer);
  
  let events = [];
  let songTracks = [];
  let locations = [];

  // 1. Parse Script Sheet
  const scriptSheet = workbook.getWorksheet('Script') || workbook.worksheets[0];
  if (scriptSheet) {
    const headerRow = scriptSheet.getRow(1);
    const headers = {};
    headerRow.eachCell((cell, colNumber) => {
      if (cell.value) {
        headers[cell.value.toString().toLowerCase().trim()] = colNumber;
      }
    });

    // Find column indices
    const colId = headers['event/effect id'] || headers['eventnum'] || headers['event id'] || headers['event_num'] || 1;
    const colFormatted = headers['time offset (mm:ss.xxx)'] || headers['time_formatted'] || 2;
    const colTitle = headers['event/effect title'] || headers['title'] || 3;
    const colMs = headers['machine time (ms)'] || headers['time_ms'] || 4;
    const colS = headers['machine time (s)'] || headers['time_s'] || 5;
    const colSong = headers['song start'] || headers['song_start'] || 6;

    const isNewFormat = Object.keys(headers).some(h => h.includes('machine time (ms)') || h.includes('time_formatted'));
    const eventsMap = {};

    scriptSheet.eachRow((row, rowNumber) => {
      if (rowNumber === 1) return; // skip header
      
      const eventNum = row.getCell(colId).value?.toString().trim();
      if (!eventNum) return;

      let ms = 0;
      if (isNewFormat) {
        const rawMs = parseInt(row.getCell(colMs).value);
        if (!isNaN(rawMs)) {
          ms = rawMs;
        } else {
          const rawS = parseFloat(row.getCell(colS).value);
          if (!isNaN(rawS)) {
            ms = Math.round(rawS * 1000);
          } else {
            // Fallback to formatted string parse
            const formatted = row.getCell(colFormatted).value?.toString().trim() || '';
            const parts = formatted.split(':');
            if (parts.length === 2) {
              const mins = parseInt(parts[0], 10);
              const secondsParts = parts[1].split('.');
              const secs = parseInt(secondsParts[0], 10);
              let msecs = 0;
              if (secondsParts.length === 2) {
                msecs = parseInt(secondsParts[1].padEnd(3, '0').substring(0, 3), 10);
              }
              ms = mins * 60000 + secs * 1000 + msecs;
            }
          }
        }
      } else {
        // Legacy Format parsing
        const colLegacyMs = headers['time offset (ms)'] || headers['offsetms'] || headers['time_ms'] || headers['time offset'] || 2;
        const colLegacyS = headers['time (s)'] || headers['offsetsec'] || headers['time_s'] || 3;
        ms = parseInt(row.getCell(colLegacyMs).value);
        if (isNaN(ms)) {
          const s = parseFloat(row.getCell(colLegacyS).value);
          if (!isNaN(s)) ms = Math.round(s * 1000);
          else ms = 0;
        }
      }

      const title = row.getCell(colTitle).value?.toString().trim() || '';
      const songName = isNewFormat ? (row.getCell(colSong).value?.toString().trim() || '') : '';

      if (!eventsMap[eventNum]) {
        eventsMap[eventNum] = {
          event_id: eventNum,
          event_num: eventNum,
          timestamp_offset_ms: ms,
          title: title,
          song: songName || undefined,
          fuseDelay: 0,
          setupNotes: '',
          relays: [],
          fireworks: []
        };
      }

      if (isNewFormat) {
        // Parse repeated column groups
        let colIdx = 7;
        while (colIdx + 4 <= row.values.length) {
          const board = row.getCell(colIdx).value?.toString().trim() || '';
          const loc = row.getCell(colIdx + 1).value?.toString().trim() || '';
          const relayVal = row.getCell(colIdx + 2).value;
          const fwName = row.getCell(colIdx + 3).value?.toString().trim() || '';
          const dur = parseFloat(row.getCell(colIdx + 4).value) || 2.0;
          const wire = row.getCell(colIdx + 5).value?.toString().trim() || '';

          colIdx += 6;

          if (loc || board || fwName) {
            eventsMap[eventNum].relays.push({
              location_id: loc,
              relay_idx: (relayVal !== undefined && relayVal !== null) ? parseInt(relayVal) : 0,
              duration_ms: Math.round(dur * 1000),
              firework_name: fwName
            });
          }
        }
      } else {
        // Legacy Format parsing
        const colFw = headers['firework name'] || headers['firework_name'] || 5;
        const colQty = headers['qty'] || headers['quantity'] || 6;
        const colLoc = headers['pallet location'] || headers['location'] || 8;
        const colRelay = headers['relay port'] || headers['relay'] || 9;
        const colFuse = headers['fuse delay (ms)'] || headers['fuse_delay'] || headers['fuse delay'] || 11;
        const colNotes = headers['setup/build notes'] || headers['notes'] || 12;

        const fwName = row.getCell(colFw).value?.toString().trim() || '';
        const qty = parseInt(row.getCell(colQty).value) || 1;
        const loc = row.getCell(colLoc).value?.toString().trim() || '';
        const relayVal = row.getCell(colRelay).value;
        const relayIdx = (relayVal !== undefined && relayVal !== null) ? parseInt(relayVal) : 0;
        const fuse = parseInt(row.getCell(colFuse).value) || 0;
        const notes = row.getCell(colNotes).value?.toString().trim() || '';

        eventsMap[eventNum].fuseDelay = fuse;
        eventsMap[eventNum].setupNotes = notes;

        if (fwName) {
          for (let q = 0; q < qty; q++) {
            eventsMap[eventNum].relays.push({
              location_id: loc,
              relay_idx: relayIdx,
              duration_ms: 2000,
              firework_name: fwName
            });
          }
        }
      }
    });

    // Reconstruct fireworks and events lists
    events = Object.values(eventsMap).map(evt => {
      // Reconstruct fireworks list from relays
      const fwGroups = {};
      evt.relays.forEach(r => {
        const name = r.firework_name || 'Unknown Firework';
        if (!fwGroups[name]) {
          fwGroups[name] = {
            firework_name: name,
            left_field: false,
            center_field: false,
            right_field: false,
            left_qty: 0,
            center_qty: 0,
            right_qty: 0,
            is_field_effect: false,
            modification: 'None',
            flash_fused: false,
            fuse_delay_sec: 0.0,
            setup_notes: ''
          };
        }
        const loc = (r.location_id || '').toUpperCase();
        if (loc.startsWith('L')) {
          fwGroups[name].left_field = true;
          fwGroups[name].left_qty++;
        } else if (loc.startsWith('C')) {
          fwGroups[name].center_field = true;
          fwGroups[name].center_qty++;
        } else if (loc.startsWith('R')) {
          fwGroups[name].right_field = true;
          fwGroups[name].right_qty++;
        }
      });
      evt.fireworks = Object.values(fwGroups);
      return evt;
    }).sort((a, b) => a.timestamp_offset_ms - b.timestamp_offset_ms);
  }

  // 2. Parse Song Tracks Sheet
  const songSheet = workbook.getWorksheet('Song Tracks');
  if (songSheet) {
    const headerRow = songSheet.getRow(1);
    const headers = {};
    headerRow.eachCell((cell, colNumber) => {
      if (cell.value) {
        headers[cell.value.toString().toLowerCase().trim()] = colNumber;
      }
    });

    const colNum = headers['song number'] || headers['song_num'] || 1;
    const colMs = headers['start time (ms)'] || headers['start_time_ms'] || 2;
    const colS = headers['start time (s)'] || headers['start_time_s'] || 3;
    const colTitle = headers['song title'] || headers['title'] || 4;
    const colArtist = headers['artist'] || 5;

    songSheet.eachRow((row, rowNumber) => {
      if (rowNumber === 1) return;
      const num = parseInt(row.getCell(colNum).value);
      if (isNaN(num)) return;

      let ms = parseInt(row.getCell(colMs).value);
      if (isNaN(ms)) {
        const s = parseFloat(row.getCell(colS).value);
        if (!isNaN(s)) ms = Math.round(s * 1000);
        else ms = 0;
      }

      const title = row.getCell(colTitle).value?.toString().trim() || `Song #${num}`;
      const artist = row.getCell(colArtist).value?.toString().trim() || 'Unknown';

      songTracks.push({
        song_num: num,
        start_time_ms: ms,
        title,
        artist
      });
    });
    songTracks.sort((a, b) => a.start_time_ms - b.start_time_ms);
  }

  // 3. Parse Locations Sheet
  const locSheet = workbook.getWorksheet('Locations');
  if (locSheet) {
    const headerRow = locSheet.getRow(1);
    const headers = {};
    headerRow.eachCell((cell, colNumber) => {
      if (cell.value) {
        headers[cell.value.toString().toLowerCase().trim()] = colNumber;
      }
    });

    const colId = headers['location id'] || headers['location_id'] || 1;
    const colHost = headers['esp32 node hostname'] || headers['node_hostname'] || 2;
    const colMac = headers['mac address'] || headers['mac_addr'] || 3;

    locSheet.eachRow((row, rowNumber) => {
      if (rowNumber === 1) return;
      const locId = row.getCell(colId).value?.toString().trim();
      if (!locId) return;

      locations.push({
        location_id: locId,
        node_hostname: row.getCell(colHost).value?.toString().trim() || '',
        mac_addr: row.getCell(colMac).value?.toString().trim() || ''
      });
    });
  }

  return { events, songTracks, locations };
}
